#include <bits/stdc++.h>
using namespace std;

// 外部函数：在 [1..n] 中用若干不同数字表示 k；返回升序解，若无解返回空向量
vector<int> pick_cards(int n, long long k) {
    long long S = 1LL * n * (n + 1) / 2;
    if (k > S) return {};  // 无解
    vector<int> ans;
    // 从大到小贪心
    for (int i = n; i >= 1; --i) {
        if (k >= i) {
            ans.push_back(i);
            k -= i;
            if (k == 0) break;
        }
    }
    if (k != 0) return {}; // 理论上不会发生
    reverse(ans.begin(), ans.end()); // 升序输出
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    if (!(cin >> T)) return 0;
    vector<string> out;
    while (T--) {
        int n, m;
        cin >> n >> m;
        for (int i = 0; i < m; ++i) {
            long long k;
            cin >> k;
            vector<int> res = pick_cards(n, k);
            if (res.empty()) {
                out.emplace_back("-1");
            } else {
                out.emplace_back(to_string((int)res.size()));
                // 拼一行升序编号
                string line;
                for (int j = 0; j < (int)res.size(); ++j) {
                    if (j) line.push_back(' ');
                    line += to_string(res[j]);
                }
                out.emplace_back(line);
            }
        }
    }
    // 统一输出
    for (auto &s : out) cout << s << "\n";
    return 0;
}
